const ExperienceCard = ({ experience, index, isExpanded, onToggle }) => {
  // Start with first image (index 0)
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [showReservationForm, setShowReservationForm] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showSuccessModal, setShowSuccessModal] = useState(false);
  const [selectedGuests, setSelectedGuests] = useState(2);
  const [reservationData, setReservationData] = useState({
    firstName: '',
    lastName: '',
    arrival: '',
    departure: '',
    guests: 2,
    wishes: '',
    email: '',
    phone: '',
    termsAccepted: false,
    marketingAccepted: false
  });

  // Calculate dynamic pricing based on guest count
  const calculatePrice = (guests) => {
    const basePrice = parseInt(experience.price.replace(/[^\d]/g, ''));
    if (guests === 1) return Math.round(basePrice * 0.7);
    if (guests === 2) return basePrice;
    if (guests === 3) return basePrice + Math.round(basePrice * 0.7);
    if (guests === 4) return basePrice * 2;
    if (guests === 5) return (basePrice * 2) + Math.round(basePrice * 0.7);
    if (guests === 6) return basePrice * 3;
    if (guests === 7) return (basePrice * 3) + Math.round(basePrice * 0.7);
    if (guests === 8) return basePrice * 4;
    return basePrice;
  };

  const currentPrice = calculatePrice(selectedGuests);

  const prevImage = (e) => {
    e.stopPropagation();
    setCurrentImageIndex(prev => 
      prev === 0 ? experience.images.length - 1 : prev - 1
    );
  };

  const nextImage = (e) => {
    e.stopPropagation();
    setCurrentImageIndex(prev => 
      prev === experience.images.length - 1 ? 0 : prev + 1
    );
  };

  const goToImage = (e, index) => {
    e.stopPropagation();
    setCurrentImageIndex(index);
  };

  const handleReservationClick = (e) => {
    e.stopPropagation();
    setShowReservationForm(true);
  };

  const handleReservationSubmit = async (e) => {
    e.preventDefault();
    setIsSubmitting(true);

    try {
      const response = await fetch('/api/reservation', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          experience: experience.title,
          ...reservationData
        }),
      });

      if (response.ok) {
        // Trigger Google Ads conversion event
        if (typeof window !== 'undefined' && typeof window.gtag_report_conversion === 'function') {
          try {
            window.gtag_report_conversion();
            console.log('Conversion event sent successfully');
          } catch (error) {
            console.error('Error sending conversion event:', error);
          }
        } else {
          console.warn('gtag_report_conversion function not available');
        }

        setShowSuccessModal(true);
        setShowReservationForm(false);
        setReservationData({
          firstName: '',
          lastName: '',
          arrival: '',
          departure: '',
          guests: 2,
          wishes: '',
          email: '',
          phone: '',
          termsAccepted: false,
          marketingAccepted: false
        });
      } else {
        throw new Error('Reservierung fehlgeschlagen');
      }
    } catch (error) {
      console.error('Error submitting reservation:', error);
      alert('Es gab einen Fehler bei der Reservierung. Bitte versuchen Sie es erneut.');
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleInputChange = (e) => {
    const { name, value, type, checked } = e.target;
    setReservationData(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value
    }));
  };

  return (
    <motion.div
      className="group"
      data-card-id={experience.id}
      initial={{ opacity: 0, y: 30 }}
      whileInView={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.6, delay: index * 0.1 }}
      viewport={{ once: true }}
    >
      {/* Collapsed State - Elegant Card */}
      {!isExpanded && (
        <motion.div
          className="bg-white rounded-2xl shadow-lg hover:shadow-xl transition-all duration-300 overflow-hidden cursor-pointer"
          onClick={() => onToggle(experience.id)}
          whileHover={{ y: -4 }}
        >
          {/* Hero Image */}
          <div className="relative h-64">
            <img 
              src={experience.image} 
              alt={experience.caption}
              className="w-full h-full object-cover"
            />

            {/* Gradient Overlay */}
            <div className="absolute inset-0 bg-gradient-to-t from-black/40 via-transparent to-transparent" />

            {/* Quick Info Badges */}
            <div className="absolute top-4 left-4 right-4 flex justify-between items-center">
              <div className="bg-white/90 backdrop-blur-sm px-3 py-1.5 rounded-full">
                <span className="text-xs font-semibold text-gray-700">{experience.travelTime}</span>
              </div>
              {experience.septemberOffer && (
                <div className="bg-coral-500 text-white px-3 py-1.5 rounded-full">
                  <span className="text-xs font-semibold">Herbst-Deal</span>
                </div>
              )}
            </div>

            {/* Location & Title */}
            <div className="absolute bottom-4 left-4 right-4 text-white">
              <div className="text-xs opacity-90 mb-1 uppercase tracking-wide">
                {experience.location}
              </div>
              <h3 className="text-xl font-bold mb-1 leading-tight">
                {experience.title}
              </h3>
              <p className="text-sm opacity-95 italic">
                {experience.caption}
              </p>
            </div>
          </div>

          {/* Card Content */}
          <div className="p-6">
            {/* Value Proposition */}
            <div className="text-center mb-6 p-4 bg-gradient-to-r from-sage-50 to-sage-100 rounded-xl border-l-4 border-coral-500">
              <h4 className="text-lg font-semibold text-gray-900 mb-2">
                Perfekt für anspruchsvolle Münchner
              </h4>
              <p className="text-sm text-gray-600 leading-relaxed">
                {experience.description}
              </p>
            </div>

            {/* Pricing Section */}
            <div className="bg-gradient-to-r from-coral-500 to-coral-600 text-white rounded-xl p-6 text-center">
              <div className="text-xs opacity-90 mb-2 uppercase tracking-wide">
                Komplettpreis ab
              </div>
              <div className="text-3xl font-bold mb-1">
                {experience.price}
              </div>
              <div className="text-sm opacity-90 mb-4">
                für 2 Personen • {experience.duration}
              </div>
              <button className="w-full bg-white text-coral-600 font-semibold py-3 px-6 rounded-xl hover:bg-gray-50 transition-colors">
                Mehr erfahren
              </button>
            </div>
          </div>
        </motion.div>
      )}

      {/* Expanded State - Full Details */}
      {isExpanded && (
        <motion.div
          initial={{ opacity: 0, scale: 0.95 }}
          animate={{ opacity: 1, scale: 1 }}
          exit={{ opacity: 0, scale: 0.95 }}
          transition={{ duration: 0.4 }}
          className="bg-white rounded-2xl shadow-xl overflow-hidden"
        >
          {/* Image Carousel */}
          <div className="relative">
            <div 
              className="relative aspect-[3/2] overflow-hidden"
              onClick={(e) => e.stopPropagation()}
            >
              <motion.img 
                key={currentImageIndex}
                src={experience.images[currentImageIndex]} 
                alt={`${experience.title} ${currentImageIndex + 1}`}
                className="w-full h-full object-cover"
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ duration: 0.3 }}
              />

              {/* Navigation arrows */}
              {experience.images.length > 1 && (
                <>
                  <button 
                    onClick={prevImage}
                    className="absolute left-3 top-1/2 -translate-y-1/2 bg-white/80 backdrop-blur-sm rounded-full p-2 shadow-lg hover:bg-white transition-colors"
                  >
                    <ChevronLeft className="w-4 h-4 text-gray-700" />
                  </button>
                  <button 
                    onClick={nextImage}
                    className="absolute right-3 top-1/2 -translate-y-1/2 bg-white/80 backdrop-blur-sm rounded-full p-2 shadow-lg hover:bg-white transition-colors"
                  >
                    <ChevronRight className="w-4 h-4 text-gray-700" />
                  </button>
                </>
              )}
            </div>

            {/* Image dots/thumbnails */}
            {experience.images.length > 1 && (
              <div 
                className="flex justify-center space-x-3 p-4"
                onClick={(e) => e.stopPropagation()}
              >
                {experience.images.map((img, index) => (
                  <button
                    key={index}
                    onClick={(e) => goToImage(e, index)}
                    className={`relative overflow-hidden rounded transition-all duration-200 ${
                      currentImageIndex === index 
                        ? 'ring-2 ring-coral-500 w-16 h-10' 
                        : 'w-12 h-8 opacity-60 hover:opacity-80'
                    }`}
                  >
                    <img 
                      src={img} 
                      alt={`Thumbnail ${index + 1}`}
                      className="w-full h-full object-cover"
                    />
                  </button>
                ))}
              </div>
            )}
          </div>

          {/* Booking Details */}
          <div className="p-6 space-y-6">
            {/* Header */}
            <div className="text-center">
              <div className="text-xs text-sage-600 uppercase tracking-wide mb-2">
                {experience.location}
              </div>
              <h3 className="text-2xl font-bold text-gray-900 mb-2">
                {experience.title}
              </h3>
              <p className="text-sage-600 italic">
                {experience.caption}
              </p>
            </div>

            {/* Value Proposition */}
            <div className="text-center p-4 bg-gradient-to-r from-sage-50 to-sage-100 rounded-xl border-l-4 border-coral-500">
              <h4 className="text-lg font-semibold text-gray-900 mb-2">
                Perfekt für anspruchsvolle Münchner
              </h4>
              <p className="text-sm text-gray-600 leading-relaxed">
                {experience.description}
              </p>
            </div>

            {/* Inclusions */}
            <div>
              <h4 className="text-lg font-semibold text-gray-900 mb-4">
                Alles inklusive für Sie:
              </h4>
              <div className="space-y-3">
                {experience.details.map((detail, index) => (
                  <div key={index} className="flex items-start space-x-3">
                    <div className="w-5 h-5 bg-coral-500 text-white rounded-full flex items-center justify-center flex-shrink-0 mt-0.5">
                      <span className="text-xs">✓</span>
                    </div>
                    <span className="text-sm text-gray-700">{detail}</span>
                  </div>
                ))}
              </div>
            </div>

            {/* Dynamic Pricing Section */}
            <div className="bg-gradient-to-r from-coral-500 to-coral-600 text-white rounded-xl p-6">
              <div className="text-center mb-6">
                <div className="text-xs opacity-90 mb-2 uppercase tracking-wide">
                  Komplettpreis ab
                </div>
                <div className="text-4xl font-bold mb-2">
                  €{currentPrice.toLocaleString('de-DE')}
                </div>
                <div className="text-sm opacity-90">
                  für {selectedGuests} Person{selectedGuests > 1 ? 'en' : ''} • {experience.duration}
                </div>
              </div>

              {/* Guest Selector */}
              <div className="bg-white/10 rounded-lg p-4 mb-6">
                <div className="text-xs opacity-90 mb-3 text-center">
                  Anzahl Personen:
                </div>
                <div className="flex justify-center gap-2 flex-wrap">
                  {[1,2,3,4,5,6,7,8].map((count) => (
                    <button
                      key={count}
                      onClick={() => setSelectedGuests(count)}
                      className={`px-3 py-2 rounded-full text-sm font-medium transition-all ${
                        selectedGuests === count
                          ? 'bg-white text-coral-600 font-semibold'
                          : 'bg-white/20 text-white hover:bg-white/30'
                      }`}
                    >
                      {count}
                    </button>
                  ))}
                </div>
              </div>

              <button 
                onClick={handleReservationClick}
                className="w-full bg-white text-coral-600 font-semibold py-4 px-6 rounded-xl hover:bg-gray-50 transition-all duration-300 shadow-lg hover:shadow-xl transform hover:-translate-y-1"
              >
                Jetzt reservieren
              </button>
            </div>

            {/* Additional Info */}
            <div className="text-center p-4 bg-sage-50 rounded-lg">
              <div className="text-xs text-sage-700">
                <strong>Flexible Buchung:</strong> Kostenlose Stornierung bis 48h vor Anreise<br />
                <strong>Anreise:</strong> Täglich nach Verfügbarkeit
              </div>
            </div>

            {/* Collapse Button */}
            <div className="flex justify-center pt-4">
              <button
                onClick={() => onToggle(experience.id)}
                className="text-sage-500 hover:text-sage-700 transition-colors"
              >
                <ChevronUp className="w-5 h-5" />
              </button>
            </div>
          </div>
        </motion.div>
      )}


        {/* Reservation Form Modal */}
        <AnimatePresence>
          {showReservationForm && (
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4"
              onClick={() => setShowReservationForm(false)}
            >
              <motion.div
                initial={{ scale: 0.9, opacity: 0 }}
                animate={{ scale: 1, opacity: 1 }}
                exit={{ scale: 0.9, opacity: 0 }}
                className="bg-white rounded-lg max-w-2xl w-full max-h-[90vh] overflow-y-auto"
                onClick={(e) => e.stopPropagation()}
              >
                {/* Header */}
                <div className="flex items-center justify-between p-6 border-b border-gray-200">
                  <div>
                    <h3 className="text-xl font-medium text-gray-900">Reservierung anfragen</h3>
                    <p className="text-sm text-gray-600 mt-1">{experience.title}</p>
                  </div>
                  <button
                    onClick={() => setShowReservationForm(false)}
                    className="text-gray-400 hover:text-gray-600 transition-colors"
                  >
                    <X className="w-6 h-6" />
                  </button>
                </div>

                {/* September Offer Message */}
                {experience.septemberOffer && (
                  <div className="px-6 pt-4 pb-2">
                    <div className="bg-gradient-to-r from-sage-50 to-sage-100 border border-sage-200 rounded-lg p-4">
                      <div className="flex items-center space-x-3 mb-3">
                        <div className="bg-gradient-to-r from-sage-500 to-sage-600 text-white px-3 py-1.5 rounded-full text-xs font-bold shadow-md">
                          September Angebot
                        </div>
                      </div>
                      <div className="space-y-2">
                        <p className="text-sm text-sage-800 font-medium">
                          Bei Buchung im September: <span className="font-bold text-lg">{experience.price}</span> statt <span className="line-through">{experience.originalPrice}</span>
                        </p>
                        <p className="text-xs text-sage-700 italic">
                          ✨ Diese außergewöhnlichen Erlebnisse sind normalerweise nicht zu diesem Preis verfügbar
                        </p>
                      </div>
                    </div>
                  </div>
                )}

                {/* Form */}
                <form onSubmit={handleReservationSubmit} className="p-6 space-y-6">
                  {/* Personal Information */}
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-2">
                        <User className="w-4 h-4 inline mr-1" />
                        Vorname *
                      </label>
                      <input
                        type="text"
                        name="firstName"
                        value={reservationData.firstName}
                        onChange={handleInputChange}
                        required
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-editorial-500 focus:border-editorial-500"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-2">
                        <User className="w-4 h-4 inline mr-1" />
                        Nachname *
                      </label>
                      <input
                        type="text"
                        name="lastName"
                        value={reservationData.lastName}
                        onChange={handleInputChange}
                        required
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-editorial-500 focus:border-editorial-500"
                      />
                    </div>
                  </div>

                  {/* Contact Information */}
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-2">
                        <Mail className="w-4 h-4 inline mr-1" />
                        E-Mail *
                      </label>
                      <input
                        type="email"
                        name="email"
                        value={reservationData.email}
                        onChange={handleInputChange}
                        required
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-editorial-500 focus:border-editorial-500"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-2">
                        <Phone className="w-4 h-4 inline mr-1" />
                        Telefonnummer
                      </label>
                      <input
                        type="tel"
                        name="phone"
                        value={reservationData.phone}
                        onChange={handleInputChange}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-editorial-500 focus:border-editorial-500"
                      />
                    </div>
                  </div>

                  {/* Travel Dates */}
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-2">
                        <Calendar className="w-4 h-4 inline mr-1" />
                        Anreise
                      </label>
                      <input
                        type="date"
                        name="arrival"
                        value={reservationData.arrival}
                        onChange={handleInputChange}
                        min={new Date().toISOString().split('T')[0]}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-editorial-500 focus:border-editorial-500"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-2">
                        <Calendar className="w-4 h-4 inline mr-1" />
                        Abreise
                        {experience.duration.includes('4') && (
                          <span className="text-xs text-amber-600 ml-1">(Mindestaufenthalt: 3 Nächte)</span>
                        )}
                      </label>
                      <input
                        type="date"
                        name="departure"
                        value={reservationData.departure}
                        onChange={handleInputChange}
                        min={reservationData.arrival || new Date().toISOString().split('T')[0]}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-editorial-500 focus:border-editorial-500"
                      />
                    </div>
                  </div>

                  {/* Guests */}
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      <Users className="w-4 h-4 inline mr-1" />
                      Anzahl Personen
                    </label>
                    <select
                      name="guests"
                      value={reservationData.guests}
                      onChange={handleInputChange}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-editorial-500 focus:border-editorial-500"
                    >
                      <option value={1}>1 Person</option>
                      <option value={2}>2 Personen</option>
                      <option value={3}>3 Personen</option>
                      <option value={4}>4 Personen</option>
                      <option value={5}>5 Personen</option>
                      <option value={6}>6 Personen</option>
                    </select>
                  </div>

                  {/* Special Wishes */}
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Erzählt uns von euren Träumen
                    </label>
                    <textarea
                      name="wishes"
                      value={reservationData.wishes}
                      onChange={handleInputChange}
                      rows={3}
                      placeholder="Was macht euren perfekten Trip aus? Besondere Erlebnisse, Diätwünsche, Allergien, romantische Überraschungen – wir hören zu und machen es möglich."
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-editorial-500 focus:border-editorial-500"
                    />
                  </div>

                  {/* Checkboxes */}
                  <div className="space-y-3">
                    <label className="flex items-start space-x-3">
                      <input
                        type="checkbox"
                        name="termsAccepted"
                        checked={reservationData.termsAccepted}
                        onChange={handleInputChange}
                        required
                        className="mt-1 h-4 w-4 text-editorial-600 focus:ring-editorial-500 border-gray-300 rounded"
                      />
                      <span className="text-sm text-gray-700">
                        Ich akzeptiere die <Link to="/agb" className="text-editorial-600 hover:underline">AGB</Link> und <Link to="/datenschutz" className="text-editorial-600 hover:underline">Datenschutzbestimmungen</Link> *
                      </span>
                    </label>
                    <label className="flex items-start space-x-3">
                      <input
                        type="checkbox"
                        name="marketingAccepted"
                        checked={reservationData.marketingAccepted}
                        onChange={handleInputChange}
                        className="mt-1 h-4 w-4 text-editorial-600 focus:ring-editorial-500 border-gray-300 rounded"
                      />
                      <span className="text-sm text-gray-700">
                        Ja, ich möchte die ersten sein, die von neuen Geheimtipps und exklusiven Angeboten erfahren – direkt in meinem Postfach
                      </span>
                    </label>
                  </div>

                  {/* Submit Button */}
                  <div className="flex space-x-4 pt-4">
                    <button
                      type="button"
                      onClick={() => setShowReservationForm(false)}
                      className="flex-1 px-6 py-3 border border-gray-300 text-gray-700 rounded-lg hover:bg-warm-50 transition-colors"
                    >
                      Abbrechen
                    </button>
                    <button
                      type="submit"
                      disabled={isSubmitting || !reservationData.termsAccepted}
                      className="flex-1 btn-primary px-6 py-3 disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                      {isSubmitting ? 'Wird gesendet...' : 'Reservierung anfragen'}
                    </button>
                  </div>
                </form>
              </motion.div>
            </motion.div>
          )}
        </AnimatePresence>

        {/* Success Modal */}
        <AnimatePresence>
          {showSuccessModal && (
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4"
              onClick={() => setShowSuccessModal(false)}
            >
              <motion.div
                initial={{ opacity: 0, scale: 0.8, y: 20 }}
                animate={{ opacity: 1, scale: 1, y: 0 }}
                exit={{ opacity: 0, scale: 0.8, y: 20 }}
                transition={{ duration: 0.4, ease: "easeOut" }}
                className="bg-white rounded-2xl p-8 md:p-12 max-w-md w-full shadow-2xl relative overflow-hidden"
                onClick={(e) => e.stopPropagation()}
              >
                {/* Decorative background elements */}
                <div className="absolute top-0 right-0 w-24 h-24 bg-coral-100 rounded-full -translate-y-12 translate-x-12"></div>
                <div className="absolute bottom-0 left-0 w-16 h-16 bg-coral-200 rounded-full translate-y-8 -translate-x-8"></div>

                {/* Content */}
                <div className="relative z-10 text-center">
                  {/* Success Icon */}
                  <div className="w-20 h-20 bg-gradient-to-br from-coral-400 to-coral-500 rounded-full flex items-center justify-center mx-auto mb-6 shadow-lg">
                    <svg className="w-10 h-10 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                    </svg>
                  </div>

                  {/* Main Message */}
                  <h3 className="text-2xl md:text-3xl font-playfair font-bold text-coral-900 mb-4 leading-tight">
                    🎉 Perfekt! Eure Anfrage ist unterwegs!
                  </h3>

                  <p className="text-lg text-coral-800 mb-6 leading-relaxed">
                    Wir freuen uns riesig auf euch! Unser Team meldet sich in den nächsten 24 Stunden bei euch mit allen Details zu eurem <strong>{experience.title}</strong>.
                  </p>

                  <div className="bg-coral-50 rounded-xl p-4 mb-6 border border-coral-200">
                    <p className="text-sm text-coral-700 font-medium">
                      💌 Checkt euer E-Mail-Postfach – dort findet ihr eine Bestätigung mit allen wichtigen Infos!
                    </p>
                  </div>

                  {/* Action Button */}
                  <button
                    onClick={() => setShowSuccessModal(false)}
                    className="w-full bg-coral-500 text-white py-4 px-6 rounded-xl font-semibold hover:bg-coral-600 transition-all duration-300 shadow-lg hover:shadow-xl transform hover:-translate-y-1"
                  >
                    Verstanden! 🚀
                  </button>
                </div>
              </motion.div>
            </motion.div>
          )}
        </AnimatePresence>
    </motion.div>
  );
};

const ExperiencesShowcase = () => {
  const [expandedCards, setExpandedCards] = useState(new Set());

  const handleToggleCard = (cardId) => {
    setExpandedCards(prev => {
      const newSet = new Set(prev);
      const wasExpanded = newSet.has(cardId);

      if (wasExpanded) {
        newSet.delete(cardId);
      } else {
        newSet.add(cardId);

        // Scroll to expanded content after animation completes
        setTimeout(() => {
          const cardElement = document.querySelector(`[data-card-id="${cardId}"]`);
          if (cardElement) {
            cardElement.scrollIntoView({ 
              behavior: 'smooth', 
              block: 'start',
              inline: 'nearest'
            });
          }
        }, 500); // Wait for expansion animation to complete
      }
      return newSet;
    });
  };

  return (
    <section className="section-padding bg-warm-50 border-b border-warm-200 relative overflow-hidden experiences-showcase">

      <div className="container-editorial relative z-10">
        <motion.div 
          className="text-center mb-16"
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8 }}
          viewport={{ once: true }}
        >
          <div className="section-badge mb-6">
            <div className="section-badge-dot"></div>
            <p className="text-caption">Unsere Erlebnisse</p>
          </div>
          <h2 className="text-section mb-6 text-editorial-900">
            Erlebnisse, die unter die Haut gehen.
          </h2>
          <p className="text-body max-w-2xl mx-auto text-editorial-700 mb-8">
            Handverlesene Wochenendtrips im Umkreis von 400km – für alle, die das Außergewöhnliche im scheinbar Gewöhnlichen finden.
          </p>

        </motion.div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 sm:gap-12 lg:gap-16">
          {experiences.map((experience, index) => (
            <ExperienceCard 
              key={experience.id} 
              experience={experience} 
              index={index}
              isExpanded={expandedCards.has(experience.id)}
              onToggle={handleToggleCard}
            />
          ))}
        </div>

        {/* Footer Note */}
      </div>
    </section>
  );
};

export default ExperiencesShowcase;
